// The PowerShell integration: the script generated by the init subcommand.
package shell

import (
	"errors"
	"fmt"
	"strings"
)

// PowerShellInit returns the PowerShell integration script, the output of
// `<prog> init powershell`: a script meant to be evaluated in an interactive
// PowerShell (Windows PowerShell 5.1 or PowerShell 7+, both built on
// PSReadLine),
//
//	wtr init powershell | Out-String | Invoke-Expression
//
// which binds key to a PSReadLine key handler opening the inline picker of bin
// right below the prompt. The widget implements the flow described in Run: it
// captures stdout, the picker renders on the terminal and reports its result
// as a mode line ("run" or "insert") followed by the command line, and the
// widget then runs it (enter) or inserts it in the prompt (tab).
//
// PSReadLine hands the line back through its own editor: GetBufferState reads
// it, Replace and AcceptLine submit the chosen command, Insert puts it at the
// cursor. No invisible sequences are needed, unlike the bash widget, because
// PSReadLine exposes the buffer to the key handler directly.
//
// prog is the name the binary was invoked as; it appears in the script's
// comments. bin is the command the widget launches — the invoked name,
// resolved through PATH at press time, or an absolute path. key is a key
// name ("ctrl-o", "alt-x"): PowerShell has no portable raw key sequences, so
// nothing else is accepted.
func PowerShellInit(prog, bin, key string) (string, error) {
	if bin == "" {
		return "", errors.New("empty binary path")
	}
	if prog == "" {
		prog = "wtr"
	}
	chord, name, err := parsePowerShellBindKey(key)
	if err != nil {
		return "", err
	}

	var b strings.Builder
	fmt.Fprintf(&b, `# %s: PowerShell integration, %s opens the inline picker.
#
# Add this line to your PowerShell profile (its path is in $PROFILE):
#
#   %s init powershell | Out-String | Invoke-Expression
#
# WTR_BIN overrides the binary the widget launches, WTR_FLAGS passes it extra
# flags (split on whitespace), e.g. $env:WTR_FLAGS = '--debug-area'.

$script:WtrBin = '%s'

# The widget bound to the key: the picker reads the console itself (stdout is
# captured to receive its result here) and reports a mode line ("run" or
# "insert") followed by the command line.
function global:Invoke-WtrWidget {
    $line = ''
    $cursor = 0
    [Microsoft.PowerShell.PSConsoleReadLine]::GetBufferState([ref]$line, [ref]$cursor)

    # Read the overrides when the key is pressed, like the zsh and bash
    # widgets: WTR_BIN picks the binary, WTR_FLAGS adds flags (split on
    # whitespace), e.g. $env:WTR_FLAGS = '--debug-area'.
    $bin = if ($env:WTR_BIN) { $env:WTR_BIN } else { $script:WtrBin }
    $flags = @()
    if ($env:WTR_FLAGS -and $env:WTR_FLAGS.Trim()) {
        $flags = $env:WTR_FLAGS.Trim() -split '\s+'
    }
    # --shell powershell: the line comes back quoted for the prompt it lands
    # in. Our own flags come first so WTR_FLAGS can override them.
    $result = @(& $bin --inline --shell powershell @flags)
    # The picker started on the prompt line and cleared its area on exit:
    # redraw the prompt and the line being edited before using the result, or
    # PSReadLine paints the command at a stale position and the prompt stays
    # erased.
    [Microsoft.PowerShell.PSConsoleReadLine]::InvokePrompt()
    if ($result.Count -lt 2) { return }

    switch ($result[0]) {
        'run' {
            # Hand the command line to PSReadLine and let it submit it: the
            # command runs like a typed line, lands in the history and leaves
            # its exit status to the prompt.
            [Microsoft.PowerShell.PSConsoleReadLine]::Replace(0, $line.Length, $result[1])
            [Microsoft.PowerShell.PSConsoleReadLine]::AcceptLine()
        }
        'insert' {
            # Put the command at the cursor; the line stays in the prompt, to
            # edit or run by hand.
            [Microsoft.PowerShell.PSConsoleReadLine]::Insert($result[1])
        }
    }
}

# Bind the key where there is a line editor to bind it to: PSReadLine ships
# with Windows PowerShell 5.1 and PowerShell 7, but a stripped session may not
# have it.
if (Get-Command Set-PSReadLineKeyHandler -ErrorAction SilentlyContinue) {
    Set-PSReadLineKeyHandler -Chord '%s' -ScriptBlock { Invoke-WtrWidget }
}
`, prog, name, prog, strings.ReplaceAll(bin, "'", "''"), chord)

	return b.String(), nil
}

// parsePowerShellBindKey turns a --key value into a PSReadLine chord and a
// human-readable name for the script's header comment: "ctrl-o" and "alt-x"
// are translated ("Ctrl+s", "Alt+x"). PowerShell has no portable raw key
// sequences — PSReadLine names the keys — so only these two forms are
// accepted.
func parsePowerShellBindKey(spec string) (chord, name string, err error) {
	key := strings.TrimSpace(spec)
	if key == "" {
		return "", "", errors.New("empty key: PowerShell takes key names like ctrl-o or alt-x, not raw sequences")
	}
	if rest, ok := cutPrefixFold(key, "ctrl-"); ok {
		if len(rest) != 1 || !isASCIILetter(rest[0]) {
			return "", "", fmt.Errorf("invalid key %q: ctrl- takes one letter, e.g. ctrl-o", spec)
		}
		return "Ctrl+" + strings.ToLower(rest), "Ctrl-" + strings.ToUpper(rest), nil
	}
	if rest, ok := cutPrefixFold(key, "alt-"); ok {
		if len(rest) != 1 || rest[0] < 0x21 || rest[0] > 0x7e {
			return "", "", fmt.Errorf("invalid key %q: alt- takes one printable character, e.g. alt-x", spec)
		}
		return "Alt+" + rest, "Alt-" + rest, nil
	}
	return "", "", fmt.Errorf("invalid key %q: PowerShell takes key names like ctrl-o or alt-x, not raw sequences", spec)
}
